sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    gs.info('PettyCashRestrict BR fired by 1 : ' + gs.getUserName() + ' sys_id=' + current.sys_id);

    var FIN_GROUP = 'PettyCash Finance Reviewers';

    var allowed = ['status', 'finance_comments'];

    // Apply only for Finance Queue rows
    //if (current.status != 'new') return;
    // if (current.line_status != 'approved') return;

    // Block ALL updates for non finance users
    if (!gs.isMemberOf(FIN_GROUP)) {

        gs.info('PettyCashRestrict BR fired by 2 : ' + gs.getUserName() + ' sys_id=' + current.sys_id);
        gs.addErrorMessage('Read-only: only Finance Reviewer can update this record.');
        current.setAbortAction(true);
        return;
    }

    // Finance users: allow ONLY status and finance_comments
    if (current.invoice_no.changes() ||
        current.total_line_amount.changes() ||
        current.receipt_upload.changes() ||
        current.description.changes() ||
        current.employee_name.changes() ||
        current.manager.changes() ||
        current.line_status.changes()) {

        // If any of these changed, block unless change is only in allowed list
        // Safer generic approach:
        //gs.info('PettyCashRestrict BR fired by 5 : ' + gs.getUserName() + ' sys_id=' + current.sys_id);
    }

    // Generic approach:
    var elements = current.getElements();
    for (var i = 0; i < elements.length; i++) {
        var f = elements[i].getName();
        if (f.startsWith('sys_') || f == 'sys_id') continue;

        if (allowed.indexOf(f) == -1 && current[f].changes()) {

            gs.info('PettyCashRestrict BR fired by 3 : ' + gs.getUserName() + ' sys_id=' + current.sys_id);
            gs.addErrorMessage('Only Finance Status and Finance Comments are allowed to update.');
            current.setAbortAction(true);
            return;
        }
    }

    gs.info('PettyCashRestrict BR fired by 4 : ' + gs.getUserName() + ' sys_id=' + current.sys_id);


})(current, previous);
